#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    vector<int> decrypt(vector<int>& code, int k) {
        int n = code.size();
        vector<int> ans(n, 0);
        if (k == 0) return ans;
        int start = k > 0 ? 1 : n + k;
        int length = abs(k), sum = 0;
        for (int j = 0; j < length; ++j) sum += code[(start + j) % n];
        for (int i = 0; i < n; ++i) {
            ans[i] = sum;
            sum -= code[(start + i) % n];
            sum += code[(start + i + length) % n];
        }
        return ans;
    }
};
